namespace ShieldbreakMaps
{
	const TArray<FName>& GetMapIds()
	{
		static const TArray<FName> Ids = { FName(TEXT("Keel")), FName(TEXT("Bastion")), FName(TEXT("Sanctum")), FName(TEXT("Creekbed")), FName(TEXT("Spire")), FName(TEXT("Crucible")) };
		return Ids;
	}

	FName GetDefaultMapId()
	{
		return FName(TEXT("Keel"));
	}

	FName Build(FName MapId, FShieldbreakMapLayout& OutLayout)
	{
		OutLayout = FShieldbreakMapLayout();
		if (MapId == FName(TEXT("Keel")))
		{
			ShieldbreakMapsData::BuildKeel(OutLayout);
			return MapId;
		}
		if (MapId == FName(TEXT("Bastion")))
		{
			ShieldbreakMapsData::BuildBastion(OutLayout);
			return MapId;
		}
		if (MapId == FName(TEXT("Sanctum")))
		{
			ShieldbreakMapsData::BuildSanctum(OutLayout);
			return MapId;
		}
		if (MapId == FName(TEXT("Creekbed")))
		{
			ShieldbreakMapsData::BuildCreekbed(OutLayout);
			return MapId;
		}
		if (MapId == FName(TEXT("Spire")))
		{
			ShieldbreakMapsData::BuildSpire(OutLayout);
			return MapId;
		}
		if (MapId == FName(TEXT("Crucible")))
		{
			ShieldbreakMapsData::BuildCrucible(OutLayout);
			return MapId;
		}
		ShieldbreakMapsData::BuildKeel(OutLayout);
		return GetDefaultMapId();
	}
}
